pub fn mesa_count_tess_level_components(mode: enum_tess_primitive_mode, arg_outer: [*c]c_uint, arg_inner: [*c]c_uint) callconv(.c) void {
    _ = &mode;
    var outer = arg_outer;
    _ = &outer;
    var inner = arg_inner;
    _ = &inner;
    blk: {
        switch (mode) {
            @as(enum_tess_primitive_mode, TESS_PRIMITIVE_ISOLINES) => {
                outer.* = 2;
                inner.* = 0;
                break :blk;
            },
            @as(enum_tess_primitive_mode, TESS_PRIMITIVE_TRIANGLES) => {
                outer.* = 3;
                inner.* = 1;
                break :blk;
            },
            else => {
                outer.* = 4;
                inner.* = 2;
                break :blk;
            },
        }
    }
}
