pub fn mesa_vertices_per_prim(arg_prim: enum_mesa_prim) callconv(.c) c_uint {
    var prim = arg_prim;
    _ = &prim;
    {
        switch (prim) {
            @as(enum_mesa_prim, MESA_PRIM_POINTS) => {
                return 1;
            },
            @as(enum_mesa_prim, MESA_PRIM_LINES), @as(enum_mesa_prim, MESA_PRIM_LINE_LOOP), @as(enum_mesa_prim, MESA_PRIM_LINE_STRIP) => {
                return 2;
            },
            @as(enum_mesa_prim, MESA_PRIM_TRIANGLES), @as(enum_mesa_prim, MESA_PRIM_TRIANGLE_STRIP), @as(enum_mesa_prim, MESA_PRIM_TRIANGLE_FAN) => {
                return 3;
            },
            @as(enum_mesa_prim, MESA_PRIM_LINES_ADJACENCY), @as(enum_mesa_prim, MESA_PRIM_LINE_STRIP_ADJACENCY) => {
                return 4;
            },
            @as(enum_mesa_prim, MESA_PRIM_TRIANGLES_ADJACENCY), @as(enum_mesa_prim, MESA_PRIM_TRIANGLE_STRIP_ADJACENCY) => {
                return 6;
            },
            @as(enum_mesa_prim, MESA_PRIM_QUADS), @as(enum_mesa_prim, MESA_PRIM_QUAD_STRIP) => {
                return 4;
            },
            else => {
                debug_printf("Unrecognized geometry or mesh shader primitive");
                return 3;
            },
        }
    }
}
pub fn u_decomposed_prims_for_vertices(arg_primitive: enum_mesa_prim, arg_vertices: c_int) callconv(.c) c_uint {
    var primitive = arg_primitive;
    _ = &primitive;
    var vertices = arg_vertices;
    _ = &vertices;
    {
        switch (primitive) {
            @as(enum_mesa_prim, MESA_PRIM_POINTS) => {
                return @bitCast(@as(c_int, vertices));
            },
            @as(enum_mesa_prim, MESA_PRIM_LINES) => {
                return @bitCast(@as(c_int, @divTrunc(vertices, @as(c_int, 2))));
            },
            @as(enum_mesa_prim, MESA_PRIM_LINE_LOOP) => {
                return @bitCast(@as(c_int, if (vertices >= @as(c_int, 2)) vertices else @as(c_int, 0)));
            },
            @as(enum_mesa_prim, MESA_PRIM_LINE_STRIP) => {
                return @bitCast(@as(c_int, if (vertices >= @as(c_int, 2)) vertices - @as(c_int, 1) else @as(c_int, 0)));
            },
            @as(enum_mesa_prim, MESA_PRIM_TRIANGLES) => {
                return @bitCast(@as(c_int, @divTrunc(vertices, @as(c_int, 3))));
            },
            @as(enum_mesa_prim, MESA_PRIM_TRIANGLE_STRIP) => {
                return @bitCast(@as(c_int, if (vertices >= @as(c_int, 3)) vertices - @as(c_int, 2) else @as(c_int, 0)));
            },
            @as(enum_mesa_prim, MESA_PRIM_TRIANGLE_FAN) => {
                return @bitCast(@as(c_int, if (vertices >= @as(c_int, 3)) vertices - @as(c_int, 2) else @as(c_int, 0)));
            },
            @as(enum_mesa_prim, MESA_PRIM_LINES_ADJACENCY) => {
                return @bitCast(@as(c_int, @divTrunc(vertices, @as(c_int, 4))));
            },
            @as(enum_mesa_prim, MESA_PRIM_LINE_STRIP_ADJACENCY) => {
                return @bitCast(@as(c_int, if (vertices >= @as(c_int, 4)) vertices - @as(c_int, 3) else @as(c_int, 0)));
            },
            @as(enum_mesa_prim, MESA_PRIM_TRIANGLES_ADJACENCY) => {
                return @bitCast(@as(c_int, @divTrunc(vertices, @as(c_int, 6))));
            },
            @as(enum_mesa_prim, MESA_PRIM_TRIANGLE_STRIP_ADJACENCY) => {
                return @bitCast(@as(c_int, if (vertices >= @as(c_int, 6)) @as(c_int, 1) + @divTrunc(vertices - @as(c_int, 6), @as(c_int, 2)) else @as(c_int, 0)));
            },
            @as(enum_mesa_prim, MESA_PRIM_QUADS) => {
                return @bitCast(@as(c_int, @divTrunc(vertices, @as(c_int, 4))));
            },
            @as(enum_mesa_prim, MESA_PRIM_QUAD_STRIP) => {
                return @bitCast(@as(c_int, if (vertices >= @as(c_int, 4)) @divTrunc(vertices - @as(c_int, 2), @as(c_int, 2)) else @as(c_int, 0)));
            },
            else => {
                debug_printf("Invalid decomposition primitive!\n");
                return @bitCast(@as(c_int, if (vertices >= @as(c_int, 3)) @as(c_int, 1) else @as(c_int, 0)));
            },
        }
    }
}
pub fn u_decomposed_prim(arg_prim: enum_mesa_prim) callconv(.c) enum_mesa_prim {
    var prim = arg_prim;
    _ = &prim;
    {
        switch (prim) {
            @as(enum_mesa_prim, MESA_PRIM_LINE_LOOP), @as(enum_mesa_prim, MESA_PRIM_LINE_STRIP) => {
                return MESA_PRIM_LINES;
            },
            @as(enum_mesa_prim, MESA_PRIM_TRIANGLE_STRIP), @as(enum_mesa_prim, MESA_PRIM_TRIANGLE_FAN) => {
                return MESA_PRIM_TRIANGLES;
            },
            @as(enum_mesa_prim, MESA_PRIM_QUAD_STRIP) => {
                return MESA_PRIM_QUADS;
            },
            @as(enum_mesa_prim, MESA_PRIM_LINE_STRIP_ADJACENCY) => {
                return MESA_PRIM_LINES_ADJACENCY;
            },
            @as(enum_mesa_prim, MESA_PRIM_TRIANGLE_STRIP_ADJACENCY) => {
                return MESA_PRIM_TRIANGLES_ADJACENCY;
            },
            else => {
                return prim;
            },
        }
    }
}
pub fn u_reduced_prim(arg_prim: enum_mesa_prim) callconv(.c) enum_mesa_prim {
    var prim = arg_prim;
    _ = &prim;
    {
        switch (prim) {
            @as(enum_mesa_prim, MESA_PRIM_POINTS) => {
                return MESA_PRIM_POINTS;
            },
            @as(enum_mesa_prim, MESA_PRIM_LINES), @as(enum_mesa_prim, MESA_PRIM_LINE_LOOP), @as(enum_mesa_prim, MESA_PRIM_LINE_STRIP), @as(enum_mesa_prim, MESA_PRIM_LINES_ADJACENCY), @as(enum_mesa_prim, MESA_PRIM_LINE_STRIP_ADJACENCY) => {
                return MESA_PRIM_LINES;
            },
            else => {
                return MESA_PRIM_TRIANGLES;
            },
        }
    }
}
pub fn mesa_prim_has_adjacency(arg_prim: enum_mesa_prim) callconv(.c) bool {
    var prim = arg_prim;
    _ = &prim;
    comptime {
        if (!(MESA_PRIM_LINE_STRIP_ADJACENCY == (MESA_PRIM_LINES_ADJACENCY + @as(c_int, 1)))) @compileError("static assertion failed \"\"");
    }
    comptime {
        if (!(MESA_PRIM_TRIANGLES_ADJACENCY == (MESA_PRIM_LINES_ADJACENCY + @as(c_int, 2)))) @compileError("static assertion failed \"\"");
    }
    comptime {
        if (!(MESA_PRIM_TRIANGLE_STRIP_ADJACENCY == (MESA_PRIM_LINES_ADJACENCY + @as(c_int, 3)))) @compileError("static assertion failed \"\"");
    }
    return (prim >= @as(enum_mesa_prim, MESA_PRIM_LINES_ADJACENCY)) and (prim <= @as(enum_mesa_prim, MESA_PRIM_TRIANGLE_STRIP_ADJACENCY));
}
